/// A pure helper: returns true iff `n` is a power of two (and positive).
/// Kept as a "spec-like" function, but implemented normally in Rust.
pub fn is_2_pow(n: i64) -> bool {
    n > 0 && (n & (n - 1)) == 0
}

/// Lower-bound (first index with a[idx] >= x) within the sorted range [lo, hi).
///
/// Preconditions (caller must satisfy):
